-- Frozen snapshot of standard-message.json compiled with compileTemplate.
-- Do not regenerate an applied migration; publish a new template version instead.
-- The creator FK requires an account on fresh databases. Bootstrap only LTaylor,
-- using the normal demo seed profile, and never overwrite existing accounts.
DO $bootstrap$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM message_templates WHERE key='standard-message' OR lower(name)=lower('Standard Message')) THEN
    INSERT INTO commands(name) VALUES ('COMSUBLANT NORFOLK VA') ON CONFLICT DO NOTHING;
    INSERT INTO users(login,name,command_id,profile)
      SELECT 'LTaylor','LT Taylor',id,'{"rank":"LT","community":"Submarine Warfare","billet":"Communications Officer","unit":"COMSUBLANT N6","command":"Commander, Submarine Force Atlantic","commandSource":"COMSUBLANT","location":"Ashore","email":"taylor.j@example.mil","dsn":"312-555-1234","roles":[{"name":"Message Viewer","detail":"View messages and attachments","granted":true},{"name":"Briefing Creator","detail":"Create and customize briefings","granted":true},{"name":"Subscription Requester","detail":"Request subscriptions for approval","granted":true},{"name":"Report Viewer","detail":"Acknowledgement and traffic reports","granted":true},{"name":"Subscription Approver","detail":"Approve unit subscription requests","granted":true},{"name":"Designated Release Authority","detail":"Release outgoing command traffic","granted":false},{"name":"System Admin","detail":"Manage unit users and settings","granted":true}],"groups":["COMSUBLANT","COMSUBLANT N6","Comms Division"]}'::jsonb FROM commands WHERE name='COMSUBLANT NORFOLK VA'
      ON CONFLICT DO NOTHING;
  END IF;
END $bootstrap$;
SET LOCAL standard_conforming_strings = on;
SELECT pg_advisory_xact_lock(hashtextextended('seed-template:standard-message', 0));
DO $seed$
DECLARE author uuid; template uuid;
BEGIN
  -- Recognize the UI-authored original as well as the stable seed key. Never
  -- overwrite, republish or reactivate an existing template, even if revised.
  IF EXISTS (SELECT 1 FROM message_templates WHERE key = 'standard-message' OR lower(name) = lower('Standard Message')) THEN
    RAISE NOTICE 'Standard Message already exists; preserving its definitions and versions';
    RETURN;
  END IF;
  SELECT id INTO author FROM users WHERE login = 'LTaylor';
  IF author IS NULL THEN RAISE EXCEPTION 'Run db:seed:users before db:seed:templates'; END IF;
  PERFORM id FROM reference_sources WHERE key = 'recipient-commands' AND contract_version = 1 AND enabled FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'The command directory source must be enabled before seeding templates'; END IF;
  INSERT INTO message_templates (key, name, description, created_by)
    VALUES ('standard-message', 'Standard Message', 'Template for a typical message', author)
    RETURNING id INTO template;
  INSERT INTO message_template_versions
    (template_id, version, input_schema, ui_schema, output_definition, formatting_profile, renderer_version, created_by, published_at)
    VALUES (template, 1, '{"$schema":"https://json-schema.org/draft/2020-12/schema","type":"object","additionalProperties":false,"properties":{"Precedence":{"type":"string","enum":["R - Routine","P - Priority","O - Immediate","Z - Flash"]},"Message DateTime":{"type":"string","maxLength":5000,"minLength":1},"Recipient Commands":{"type":"array","uniqueItems":true,"items":{"type":"string","format":"uuid"},"minItems":1},"Info Commands":{"type":"array","uniqueItems":true,"items":{"type":"string","format":"uuid"},"minItems":1},"Classification":{"type":"string","maxLength":5000,"minLength":1},"Msg Type":{"type":"string","maxLength":5000,"minLength":1},"Subject":{"type":"string","maxLength":5000,"minLength":1},"Point of Contact":{"type":"string","maxLength":5000,"minLength":1},"Body":{"type":"string","maxLength":5000,"minLength":1},"Message Number":{"type":"string","maxLength":5000,"minLength":1}},"required":["Precedence","Message DateTime","Recipient Commands","Info Commands","Classification","Msg Type","Subject","Point of Contact","Body","Message Number"]}'::jsonb, '{"fields":[{"name":"Precedence","control":"select","required":true,"options":["R - Routine","P - Priority","O - Immediate","Z - Flash"],"optionOutputs":{"R - Routine":"R","P - Priority":"P","O - Immediate":"O","Z - Flash":"Z"}},{"name":"Message DateTime","control":"text","required":true,"options":[]},{"name":"Origin Command","control":"autogenerated","required":true,"options":[],"generator":{"key":"sending-command","version":1}},{"name":"Recipient Commands","control":"command-multiple","required":true,"options":[],"separator":"newline","reference":{"source":"recipient-commands","contractVersion":1,"parameters":{}}},{"name":"Info Commands","control":"command-multiple","required":true,"options":[],"separator":"newline","reference":{"source":"recipient-commands","contractVersion":1,"parameters":{}}},{"name":"Classification","control":"text","required":true,"options":[]},{"name":"Msg Type","control":"text","required":true,"options":[]},{"name":"Subject","control":"text","required":true,"options":[]},{"name":"Point of Contact","control":"text","required":true,"options":[]},{"name":"Body","control":"text","required":true,"options":[]},{"name":"Message Number","control":"text","required":true,"options":[]}]}'::jsonb, '{"format":"plaintext","body":"TODO: figure out header\n{{ Precedence }} {{ Message DateTime }}\nFM {{ Origin Command }}\nTO {{ Recipient Commands }}\nINFO {{ Info Commands }}\nBT\n{{ Classification }}//\nMSGID/{{ Msg Type }}/{{ Origin Command }}//\nSUBJ/{{ Subject }}//\nPOC/{{ Point of Contact }}//\nRMKS/{{ Body }}//\nBT\n{{ Message Number }}\nNNNN","placeholderSyntax":"named-v1"}'::jsonb,
      '{"version":1,"wordWrap":false,"newline":"LF"}'::jsonb, 'named-v1', author, now());
END $seed$;
